import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Worker Leases, Failure Classification and Recovery","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/job-recovery","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/job-recovery.md","filePath":"en/tutorials/job-recovery.md"}'),r={name:"en/tutorials/job-recovery.md"};function i(o,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="worker-leases-failure-classification-and-recovery" tabindex="-1">Worker Leases, Failure Classification and Recovery <a class="header-anchor" href="#worker-leases-failure-classification-and-recovery" aria-label="Permalink to &quot;Worker Leases, Failure Classification and Recovery&quot;">​</a></h1><p>Goal: keep finite budgets through crashes, external outages and administrator retries. Implement <a href="./document-exports">Handler/publication transactions</a> first. Jobs coordinates reliable execution; your business still owns external-effect idempotency.</p><h2 id="claiming-consumes-an-attempt" tabindex="-1">Claiming Consumes an Attempt <a class="header-anchor" href="#claiming-consumes-an-attempt" aria-label="Permalink to &quot;Claiming Consumes an Attempt&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Core Jobs</a> increments attempts, creates a distinct lease_token and records the attempt in the claim transaction. An immediate crash still consumes budget. After expiry another Worker claims only within remaining budget; exhaustion becomes failed.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  queued --&gt; running: claim / attempts + 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; succeeded: fenced commit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; retry_wait: transient / budget remains</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  retry_wait --&gt; running: scheduled claim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  running --&gt; failed: permanent or exhausted</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  failed --&gt; queued: explicit admin batch</span></span></code></pre></div><p><code>JobError::Transient(&quot;static.code&quot;)</code> retries with bounded exponential backoff/full jitter; <code>Permanent</code> terminates; <code>LostLease</code> prevents stale terminal writes. Persist static safe codes, never formatted storage errors, payloads or secrets.</p><h2 id="fence-the-result" tabindex="-1">Fence the Result <a class="header-anchor" href="#fence-the-result" aria-label="Permalink to &quot;Fence the Result&quot;">​</a></h2><p><code>Lease::lock_current(connection)</code> checks current token, running and valid expiry while locking the row. <code>succeed(connection)</code> updates Job, attempt/batch and notification in the caller&#39;s transaction. Business result, Audit and succeed commit together. See <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">actual interfaces</a>.</p><p>After another Worker takes over, the first cannot overwrite results with its old token even after successful I/O. A fence cannot retract sent mail or remote effects; use immutable candidates, unique business constraints or remote idempotency keys.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker loop</a> drives Handler and heartbeat independently, allowing publication to advance while renewal waits for locks. Failed renewal cancels the Handler future/releases its transaction before a bounded failure write. Shutdown stops new claims and drains finitely; timeout leaves the running lease to expire rather than releasing still-active effects early.</p><p>Defaults are 60/20/10 seconds for lease/heartbeat/drain; see <a href="./../reference/config">configuration</a>. Blocking work needs cooperative cancellation because started <code>spawn_blocking</code> cannot be forcibly aborted.</p><h2 id="reuse-administrator-recovery" tabindex="-1">Reuse Administrator Recovery <a class="header-anchor" href="#reuse-administrator-recovery" aria-label="Permalink to &quot;Reuse Administrator Recovery&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/management.rs" target="_blank" rel="noreferrer">Management API</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/administration.rs" target="_blank" rel="noreferrer">use cases</a> require current Owner/Admin. Retrying a failure preserves Job ID, business payload/snapshot and old history while explicitly starting a new finite batch. Idempotency and Audit share the transaction; successful Jobs cannot reopen.</p><p>Management responses omit payload and lease_token. List cursors bind identity/status and history is bounded. Retry transient failures after restoring dependencies. Administrator retry does not restore revoked credentials, access or expired snapshots; an eligible user must submit a new request.</p><h2 id="verify-controlled-failures" tabindex="-1">Verify Controlled Failures <a class="header-anchor" href="#verify-controlled-failures" aria-label="Permalink to &quot;Verify Controlled Failures&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Public Jobs checks</a> cover crash budgets, takeover, stale rejection, bounded shutdown and backoff. <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/jobs.rs" target="_blank" rel="noreferrer">Management checks</a> cover authorization, batches/history, idempotency and Audit rollback. Real locks/synchronization organize races, while database timestamps establish time boundaries without random sleeps.</p><p>Add a lost-lease publication check to your Handler and classify permanent/transient errors. Continue with <a href="./deletion-cleanup">business deletion/cleanup</a>; registered <a href="./export-notifications">notifications</a> publish in terminal transactions.</p><hr><p>Source version：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/11-job-recovery.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,22)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
